mkdir -p inspect cmd/inspect-demo && cat > inspect/inspect.go <<'EOF'
// Package inspect provides deep pretty-printing of arbitrary Go values for
// debugging. It wraps github.com/davecgh/go-spew with defaults suited to
// interactive inspection.
package inspect

import (
	"io"
	"os"

	"github.com/davecgh/go-spew/spew"
)

// Config is the default configuration used by the package-level helpers.
// Callers may copy and tweak it for custom behavior.
var Config = spew.ConfigState{
	Indent:                  "  ",
	SortKeys:                true, // deterministic map output
	DisablePointerAddresses: false,
	DisableCapacities:       true,
	DisableMethods:          true, // show raw fields rather than String()/Error()
	MaxDepth:                0,    // unlimited; cycles are detected automatically
}

// Dump writes a deep, typed representation of each value to stdout.
func Dump(vs ...any) { Config.Fdump(os.Stdout, vs...) }

// Fdump writes a deep, typed representation of each value to w.
func Fdump(w io.Writer, vs ...any) { Config.Fdump(w, vs...) }

// Sdump returns a deep, typed representation of each value as a string.
func Sdump(vs ...any) string { return Config.Sdump(vs...) }
EOF
cat > inspect/inspect_test.go <<'EOF'
package inspect

import (
	"strings"
	"testing"
)

type node struct {
	Name     string
	Children []*node
	Meta     map[string]int
	parent   *node
}

func TestSdumpNestedAndCyclic(t *testing.T) {
	root := &node{Name: "root", Meta: map[string]int{"b": 2, "a": 1}}
	child := &node{Name: "child", parent: root}
	root.Children = append(root.Children, child)

	out := Sdump(root)
	for _, want := range []string{`"root"`, `"child"`, "parent:", "already shown"} {
		if !strings.Contains(out, want) {
			t.Errorf("output missing %q:\n%s", want, out)
		}
	}
	if strings.Index(out, `"a"`) > strings.Index(out, `"b"`) {
		t.Errorf("map keys not sorted:\n%s", out)
	}
}
EOF
cat > cmd/inspect-demo/main.go <<'EOF'
// Command inspect-demo shows the inspect package in action.
package main

import "github.com/example/inspect/inspect"

type Config struct {
	Name    string
	Ports   []int
	Labels  map[string]string
	Backend *Backend
}

type Backend struct {
	Host string
	TLS  bool
}

func main() {
	inspect.Dump(Config{
		Name:    "svc",
		Ports:   []int{80, 443},
		Labels:  map[string]string{"env": "prod", "app": "web"},
		Backend: &Backend{Host: "10.0.0.1", TLS: true},
	})
}
EOF
go mod tidy && go vet ./... && go test ./... && go run ./cmd/inspect-demo

